package com.renthouse.notification;import com.renthouse.auth.*;import com.renthouse.common.api.*;import java.time.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/notifications")public class NotificationController{private final JdbcTemplate j;public NotificationController(JdbcTemplate j){this.j=j;}@GetMapping public ApiResponse<PageResponse<Item>>list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){long u=CurrentUser.require().id();page=Math.max(1,page);size=Math.min(50,Math.max(1,size));Long t=j.queryForObject("SELECT COUNT(*) FROM system_notification WHERE recipient_id=?",Long.class,u);return ApiResponse.ok(PageResponse.of(j.query("SELECT * FROM system_notification WHERE recipient_id=? ORDER BY created_at DESC LIMIT ? OFFSET ?",(r,n)->new Item(""+r.getLong("id"),r.getString("notification_type"),r.getString("title"),r.getString("content"),r.getTimestamp("read_at")==null,r.getTimestamp("created_at").toLocalDateTime()),u,size,(page-1)*size),t==null?0:t,page,size));}@GetMapping("/unread-count")public ApiResponse<Long>unread(){Long n=j.queryForObject("SELECT COUNT(*) FROM system_notification WHERE recipient_id=? AND read_at IS NULL",Long.class,CurrentUser.require().id());return ApiResponse.ok(n==null?0:n);}@PostMapping("/{id}/read")public ApiResponse<Void>read(@PathVariable long id){j.update("UPDATE system_notification SET read_at=? WHERE id=? AND recipient_id=?",LocalDateTime.now(),id,CurrentUser.require().id());return ApiResponse.ok();}@PostMapping("/read-all")public ApiResponse<Void>readAll(){j.update("UPDATE system_notification SET read_at=? WHERE recipient_id=? AND read_at IS NULL",LocalDateTime.now(),CurrentUser.require().id());return ApiResponse.ok();}public record Item(String id,String type,String title,String content,boolean unread,LocalDateTime createdAt){}}
